def merge_config(base, patch):
    if not isinstance(base, dict) or not isinstance(patch, dict):
        raise ValueError("Both base and patch must be dictionaries")
    result = base.copy()
    for key, value in patch.items():
        if key in result:
            if isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = merge_config(result[key], value)
            elif value is None:
                result[key] = None
            else:
                result[key] = value
        else:
            result[key] = value
    return result

from pathlib import Path
from datetime import datetime

def report_paths(root):
    paths = []
    for path in Path(root).iterdir():
        if path.is_file() and path.name.startswith("report-") and path.name.endswith(".csv"):
            date_str = path.name[7:-4]
            date = datetime.strptime(date_str, "%Y-%m-%d")
            paths.append((date, path))
    return sorted(paths, key=lambda x: x[0])

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("Invalid input values")
    start = page * size
    stop = min(start + size, total)
    return start, stop

def summarize_jobs(jobs):
    summary = {}
    for job in jobs:
        status = job.status
        size = job.size
        if status not in summary:
            summary[status] = (0, 0)
        summary[status] = (summary[status][0] + 1, summary[status][1] + size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

def retry_read(read, attempts):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            pass
    raise TimeoutError("All attempts timed out")

def iter_unique_events(events):
    seen_ids = set()
    for event in events:
        if event.get('id') is not None:
            seen_ids.add(event['id'])
        yield event

def render_row(fields, record, missing="-"):
    def escape(s):
        return s.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n")
    return "\t".join(map(lambda field: escape(str(record[field] if record[field] is not None else missing)), fields))
